                    let mut res = nums[i];
                    for &j in &g[i] {
                        if j != fa {
                            let s2 = sub[j];
                            res ^= s2;
                            let mx = (s ^ s1).max(s2).max(s1 ^ s2);
                            let mn = (s ^ s1).min(s2).min(s1 ^ s2);
                            ans = ans.min(mx - mn);
                        }
                    }
                    sub[i] = res;
                }
            }
            ans
        }

        let mut ans = i32::MAX;
        for i in 0..n {
            for &j in &g[i] {
                let s1 = component_xor(i, j, &g, &nums);
                ans = ans.min(collect(i, j, &g, &nums, s, s1));
            }
        }
        ans
    }
}

public class Solution {
    public int MinimumScore(int[] nums, int[][] edges) {
        int n = nums.Length;
        List<int>[] g = new List<int>[n];
        for (int i = 0; i < n; i++) {
            g[i] = new List<int>();
        }
        foreach (var e in edges) {
            int a = e[0], b = e[1];
            g[a].Add(b);
            g[b].Add(a);
        }

        int s = 0;
        foreach (int x in nums) {
            s ^= x;
        }

        int ComponentXor(int root, int ban) {
            int[] sub = new int[n];
            var stk = new Stack<int[]>();
            stk.Push(new int[] { root, ban, 0 });
            while (stk.Count > 0) {
                int[] cur = stk.Pop();
                int i = cur[0], fa = cur[1], state = cur[2];
                if (state == 0) {
                    stk.Push(new int[] { i, fa, 1 });
                    foreach (int j in g[i]) {
                        if (j != fa) {
                            stk.Push(new int[] { j, i, 0 });
                        }
                    }
                } else {
                    int res = nums[i];
                    foreach (int j in g[i]) {
                        if (j != fa) {
                            res ^= sub[j];
                        }
                    }
                    sub[i] = res;
                }
            }
            return sub[root];
        }

        int Collect(int root, int ban, int s1) {
            int best = int.MaxValue;
            int[] sub = new int[n];
            var stk = new Stack<int[]>();
            stk.Push(new int[] { root, ban, 0 });
            while (stk.Count > 0) {
                int[] cur = stk.Pop();
                int i = cur[0], fa = cur[1], state = cur[2];
                if (state == 0) {
                    stk.Push(new int[] { i, fa, 1 });
                    foreach (int j in g[i]) {
                        if (j != fa) {
                            stk.Push(new int[] { j, i, 0 });
                        }
                    }
                } else {
                    int res = nums[i];
                    foreach (int j in g[i]) {
                        if (j != fa) {
                            int s2 = sub[j];
                            res ^= s2;
                            int mx = Math.Max(Math.Max(s ^ s1, s2), s1 ^ s2);
                            int mn = Math.Min(Math.Min(s ^ s1, s2), s1 ^ s2);
                            best = Math.Min(best, mx - mn);
                        }
                    }
                    sub[i] = res;
                }
            }
            return best;
        }

        int ans = int.MaxValue;
        for (int i = 0; i < n; ++i) {
            foreach (int j in g[i]) {
                int s1 = ComponentXor(i, j);
                ans = Math.Min(ans, Collect(i, j, s1));
            }
        }
        return ans;
    }
}

impl Solution {
    pub fn minimum_score(nums: Vec<i32>, edges: Vec<Vec<i32>>) -> i32 {
        let n = nums.len();
        let mut g = vec![vec![]; n];
        for e in edges.iter() {
            let a = e[0] as usize;
            let b = e[1] as usize;
            g[a].push(b);
            g[b].push(a);
        }
        let mut s1 = 0;
        let mut ans = i32::MAX;
        let s = nums.iter().fold(0, |acc, &x| acc ^ x);

        fn dfs(i: usize, fa: usize, g: &Vec<Vec<usize>>, nums: &Vec<i32>) -> i32 {
            let mut res = nums[i];
            for &j in &g[i] {
                if j != fa {
                    res ^= dfs(j, i, g, nums);
                }
            }
            res
        }

        fn dfs2(
            i: usize,
            fa: usize,
            g: &Vec<Vec<usize>>,
            nums: &Vec<i32>,
            s: i32,
            s1: i32,
            ans: &mut i32,
        ) -> i32 {
            let mut res = nums[i];
            for &j in &g[i] {
                if j != fa {
                    let s2 = dfs2(j, i, g, nums, s, s1, ans);
                    res ^= s2;
                    let mx = (s ^ s1).max(s2).max(s1 ^ s2);
                    let mn = (s ^ s1).min(s2).min(s1 ^ s2);
                    *ans = (*ans).min(mx - mn);
                }
            }
            res
        }

        for i in 0..n {
            for &j in &g[i] {
                s1 = dfs(i, j, &g, &nums);
                dfs2(i, j, &g, &nums, s, s1, &mut ans);
            }
        }
        ans
    }
}
